// Construct a random BPF program (instruction array) with bounded length.
int prog_len = (int)(*FUZZ_PARAM(unsigned int) % 64); // keep small for speed
if (prog_len < 0) { FUZZ_BAIL(); }
struct bpf_insn *program = nullptr;
if (prog_len > 0) {
    program = new struct bpf_insn[(size_t)prog_len];
    for (int i = 0; i < prog_len; ++i) {
        program[i].code = (u_short)(*FUZZ_PARAM(uint16_t));
        program[i].jt   = (u_char)(*FUZZ_PARAM(uint8_t));
        program[i].jf   = (u_char)(*FUZZ_PARAM(uint8_t));
        program[i].k    = (bpf_u_int32)(*FUZZ_PARAM(uint32_t));
    }
}

// Validate the program before executing it, per API requirement.
int valid = bpf_validate(program, prog_len);
if (!valid) {
    // Clean up and bail if program is invalid to avoid undefined behavior in bpf_filter.
    if (program) { delete[] program; program = nullptr; }
    FUZZ_BAIL();
}

// Generate a random packet buffer; enforce length consistency constraints.
std::string pkt = FUZZ_PARAM_STR();
size_t pkt_size = pkt.size();
if (pkt_size > 2048) {
    // Trim for performance; safe because we won't read beyond these lengths.
    pkt_size = 2048;
}
// Choose packet_len in [0, pkt_size]
unsigned int packet_len = (unsigned int)(*FUZZ_PARAM(uint32_t) % (pkt_size + 1));
// Choose buffer_len in [packet_len, pkt_size]
unsigned int buffer_len = packet_len + (unsigned int)(*FUZZ_PARAM(uint32_t) % (pkt_size - packet_len + 1));

// Safety: require non-null packet pointer when lengths are non-zero; FUZZ_PARAM_STR guarantees data().
const u_char *packet_ptr = (const u_char *)pkt.data();
if ((packet_len > 0 || buffer_len > 0) && packet_ptr == nullptr) {
    if (program) { delete[] program; program = nullptr; }
    FUZZ_BAIL();
}

// Execute the validated filter. Return value is bytes accepted; 0 means reject.
volatile u_int accepted = bpf_filter(program, packet_ptr, packet_len, buffer_len);
(void)accepted; // Prevent unused warning, side-effect free.

// Clean up owned memory.
if (program) { delete[] program; program = nullptr; }

// Validation summary: Ensures program is validated via bpf_validate before bpf_filter and that packet_len/buffer_len do not exceed the available buffer size; bails on violations.

// Build a random instruction array; allow zero-length to exercise edge paths.
int len = (int)(*FUZZ_PARAM(unsigned int) % 64); // 0..63 instructions
if (len < 0) { FUZZ_BAIL(); }
struct bpf_insn *insns = nullptr;
if (len > 0) {
    insns = new struct bpf_insn[(size_t)len];
    for (int i = 0; i < len; ++i) {
        insns[i].code = (u_short)(*FUZZ_PARAM(uint16_t));
        insns[i].jt   = (u_char)(*FUZZ_PARAM(uint8_t));
        insns[i].jf   = (u_char)(*FUZZ_PARAM(uint8_t));
        insns[i].k    = (bpf_u_int32)(*FUZZ_PARAM(uint32_t));
    }
}

// Invoke the validator; caller should use the result to gate execution elsewhere.
volatile int ok = bpf_validate(insns, len);
(void)ok;

// Clean up local allocation.
if (insns) { delete[] insns; insns = nullptr; }

// Validation summary: Supplies a well-formed array (possibly empty), stays within bounds, and performs no execution; no persistent objects are leaked.

// Construct a small random BPF program and (optionally) validate it before imaging.
